def ensure_directory(file_path: str) -> bool:
    """确保文件所在目录存在"""
    try:
        dir_path = os.path.dirname(file_path)
        if dir_path and not os.path.exists(dir_path):
            os.makedirs(dir_path)
        return True
    except Exception:
        return False

